<?php $classLabels = ['Fisico' => 'Físico', 'Quimico' => 'Químico', 'Biologico' => 'Biológico', 'Biomecanico' => 'Biomecánico', 'Psicosocial' => 'Psicosocial', 'Seguridad' => 'Seguridad', 'Publico' => 'Público', 'Natural' => 'Natural', 'Tecnologico' => 'Tecnológico']; ?>
<div class="page-heading"><div><span class="eyebrow">Identificar · Evaluar · Controlar</span><h1>Matriz IPEVR</h1><p>Peligros, efectos y controles priorizados según la realidad de <?= e($tenant['razonsocial']) ?>.</p></div><a href="#nuevo-peligro" class="btn-primary"><?= icon('plus', 'h-4 w-4') ?> Agregar peligro</a></div>
<section class="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-4"><?php foreach ([['Peligros identificados', (int) $stats['total'], 'grid'], ['Prioritarios activos', (int) $stats['prioritarios'], 'alert'], ['Controlados', (int) $stats['controlados'], 'check-circle'], ['Actividad CIIU', $tenant['codigo_ciuu'] ?? 'N/D', 'briefcase']] as $item): ?><div class="ios-card p-4"><div class="flex items-center gap-2 text-slate-400"><?= icon($item[2], 'h-4 w-4') ?><p class="text-[11px]"><?= e($item[0]) ?></p></div><p class="mt-3 truncate text-xl font-semibold tracking-tight"><?= e($item[1]) ?></p></div><?php endforeach; ?></section>
<div class="mt-5 rounded-2xl bg-amber-50 p-4 text-[11px] leading-5 text-amber-800 ring-1 ring-amber-100"><div class="flex gap-2"><?= icon('info', 'mt-0.5 h-4 w-4 shrink-0') ?><p>La matriz sectorial es un punto de partida. Valida cada peligro por proceso, cargo, actividad rutinaria y no rutinaria, con participación de los trabajadores. El cálculo ND×NE×NC es orientativo y debe armonizarse con la metodología formalmente adoptada.</p></div></div>
<section class="ios-card mt-5 overflow-hidden"><div class="card-heading"><div><h2>Inventario de peligros y riesgos</h2><p>Ordenado por prioridad de intervención.</p></div><form method="get" action="<?= e(url('/matriz-ipevr')) ?>" class="flex gap-2"><select name="clasificacion" class="input h-9 !w-auto text-xs"><option value="">Todas las clases</option><?php foreach ($classifications as $class): ?><option value="<?= e($class) ?>"<?= selected($classification, $class) ?>><?= e($classLabels[$class]) ?></option><?php endforeach; ?></select><button class="btn-secondary h-9" type="submit">Filtrar</button></form></div>
<?php if ($hazards === []): ?><div class="empty-state"><span class="empty-icon"><?= icon('grid', 'h-7 w-7') ?></span><h3>No hay peligros en esta vista</h3><p>Agrega un peligro o cambia el filtro de clasificación.</p></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Proceso y peligro</th><th>Clasificación</th><th>Efectos</th><th>Valoración</th><th>Controles propuestos</th><th>Estado</th></tr></thead><tbody><?php foreach ($hazards as $hazard): ?><tr><td><div class="max-w-[330px]"><p class="text-[10px] font-semibold uppercase tracking-wider text-slate-400"><?= e($hazard['proceso']) ?> · <?= e($hazard['cargo']) ?></p><p class="mt-1.5 text-xs font-semibold leading-5 text-slate-700"><?= e($hazard['peligro']) ?></p></div></td><td><span class="badge badge-gray"><?= e($classLabels[$hazard['clasificacion']] ?? $hazard['clasificacion']) ?></span></td><td><p class="max-w-[220px] text-[11px] leading-5 text-slate-500"><?= e($hazard['efectos']) ?></p></td><td><span class="badge <?= risk_class($hazard['nivel_riesgo']) ?>"><?= e($hazard['nivel_riesgo']) ?></span><?php if ($hazard['nivel_probabilidad'] !== null): ?><p class="mt-1.5 whitespace-nowrap font-mono text-[10px] text-slate-400">NP <?= (int) $hazard['nivel_probabilidad'] ?> · NR <?= (int) $hazard['nivel_probabilidad'] * (int) $hazard['nivel_consecuencia'] ?></p><?php else: ?><p class="mt-1.5 text-[10px] text-slate-400">Valoración inicial</p><?php endif; ?></td><td><details class="max-w-[270px]"><summary class="cursor-pointer text-[11px] font-medium leading-5 text-blue-600"><?= e(excerpt($hazard['medidas_control'], 62)) ?></summary><div class="mt-2 rounded-xl bg-slate-50 p-3 text-[11px] leading-5 text-slate-600"><p><strong>Intervención:</strong> <?= e($hazard['medidas_control']) ?></p><p class="mt-2"><strong>Controles existentes:</strong> <?= e($hazard['controles_existentes']) ?></p></div></details></td><td><form method="post" action="<?= e(url('/matriz-ipevr/' . $hazard['id'] . '/estado')) ?>"><?= csrf_field() ?><input type="hidden" name="estado" value="<?= $hazard['estado'] === 'Activo' ? 'Controlado' : 'Activo' ?>"><span class="badge <?= status_class($hazard['estado']) ?>"><?= e($hazard['estado']) ?></span><button type="submit" class="mt-2 block text-[10px] font-medium text-blue-600 hover:underline"><?= $hazard['estado'] === 'Activo' ? 'Marcar controlado' : 'Reactivar' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<details id="nuevo-peligro" class="ios-card mt-6 overflow-hidden"<?= $errors !== [] ? ' open' : '' ?>><summary class="cursor-pointer list-none p-5"><div class="section-heading"><span class="section-icon"><?= icon('plus', 'h-5 w-5') ?></span><div><h2>Agregar peligro a la matriz</h2><p>Registra el contexto, los efectos y la jerarquía de controles.</p></div></div></summary><form method="post" action="<?= e(url('/matriz-ipevr')) ?>" class="border-t border-slate-100 p-5 sm:p-6" data-risk-form><?= csrf_field() ?><div class="grid gap-5 sm:grid-cols-2"><div><label class="label">Proceso *</label><input name="proceso" class="input" value="<?= e(old('proceso', 'General')) ?>" required></div><div><label class="label">Cargo o población expuesta *</label><input name="cargo" class="input" value="<?= e(old('cargo')) ?>" placeholder="Ej. Operarios de producción" required></div><div class="sm:col-span-2"><label class="label">Descripción del peligro *</label><input name="peligro" class="input" value="<?= e(old('peligro')) ?>" required><?= field_error('peligro') ?></div><div><label class="label">Clasificación *</label><select name="clasificacion" class="input"><?php foreach ($classifications as $class): ?><option value="<?= e($class) ?>"<?= selected(old('clasificacion'), $class) ?>><?= e($classLabels[$class]) ?></option><?php endforeach; ?></select></div><div><label class="label">Efectos posibles *</label><input name="efectos" class="input" value="<?= e(old('efectos')) ?>" required><?= field_error('efectos') ?></div><div class="sm:col-span-2"><label class="label">Controles existentes</label><textarea name="controles_existentes" class="input min-h-20"><?= e(old('controles_existentes')) ?></textarea></div><div class="sm:col-span-2"><label class="label">Medidas de prevención y control *</label><textarea name="medidas_control" class="input min-h-24" placeholder="Prioriza eliminación, sustitución, ingeniería, controles administrativos y finalmente EPP" required><?= e(old('medidas_control')) ?></textarea><?= field_error('medidas_control') ?></div></div><div class="mt-6 rounded-2xl bg-slate-50 p-4"><h3 class="text-xs font-semibold text-slate-700">Valoración cuantitativa opcional</h3><p class="mt-1 text-[11px] text-slate-400">Completa los tres valores para calcular NP = ND × NE y NR = NP × NC.</p><div class="mt-4 grid gap-4 sm:grid-cols-4"><div><label class="label">Deficiencia (ND)</label><select name="nivel_deficiencia" class="input" data-risk-nd><option value="">Sin valorar</option><?php foreach ([0,2,6,10] as $value): ?><option value="<?= $value ?>"<?= selected(old('nivel_deficiencia'), $value) ?>><?= $value ?></option><?php endforeach; ?></select><?= field_error('nivel_deficiencia') ?></div><div><label class="label">Exposición (NE)</label><select name="nivel_exposicion" class="input" data-risk-ne><option value="">Sin valorar</option><?php foreach ([1,2,3,4] as $value): ?><option value="<?= $value ?>"<?= selected(old('nivel_exposicion'), $value) ?>><?= $value ?></option><?php endforeach; ?></select></div><div><label class="label">Consecuencia (NC)</label><select name="nivel_consecuencia" class="input" data-risk-nc><option value="">Sin valorar</option><?php foreach ([10,25,60,100] as $value): ?><option value="<?= $value ?>"<?= selected(old('nivel_consecuencia'), $value) ?>><?= $value ?></option><?php endforeach; ?></select></div><div><label class="label">Nivel manual alternativo</label><select name="nivel_riesgo" class="input" data-risk-fallback><?php foreach (['Bajo','Medio','Alto','Critico'] as $level): ?><option<?= selected(old('nivel_riesgo', 'Medio'), $level) ?>><?= $level ?></option><?php endforeach; ?></select></div></div><div class="mt-4 flex items-center gap-3 rounded-xl bg-white p-3 text-xs"><span class="text-slate-400">Resultado orientativo:</span><strong data-risk-result>Sin valores completos</strong></div></div><div class="mt-5 flex justify-end"><button type="submit" class="btn-primary"><?= icon('plus', 'h-4 w-4') ?> Guardar en la IPEVR</button></div></form></details>
